param([Parameter(Mandatory=$true)][ValidateSet('Debug','Release')][string]$Configuration,[switch]$ExecutionAuthorized)
# Optional once-only demand task. No trigger/retry/notifier/build; root must review before execution.
$ErrorActionPreference='Stop';$Configuration=if($Configuration -ieq 'Debug'){'Debug'}else{'Release'}
$tests=Split-Path -Parent $PSScriptRoot;$tag='upl_cryer_gpu_component_'+$Configuration+'_probe_r3';$taskName='GeoDualSPH_upl_cryer_component_'+$Configuration+'_r3_20261103'
$logs=Join-Path $tests 'logs';$claim=Join-Path $logs ($tag+'.task_attempt.json');$receipt=Join-Path $logs ($tag+'.task_launch.json');$regReceipt=Join-Path $logs ($tag+'.task_registered.json');$xmlPath=Join-Path $logs ($tag+'.task.xml')
function Need([bool]$b,[string]$why){if(!$b){throw $why}}
function E([string]$p){$f=Get-Item -LiteralPath ([IO.Path]::GetFullPath($p));Need (!$f.PSIsContainer) 'Expected file';return [ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}
function V($entries){foreach($e in @($entries)){$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ceq $e.sha256) ('Changed launch input: '+$e.path)}}
function J([string]$p){return ([IO.File]::ReadAllText($p)|ConvertFrom-Json)}
function Fresh($paths){foreach($p in @($paths)){Need (!(Test-Path -LiteralPath $p)) ('Retained artifact protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 15)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function Quoted([string]$s){Need ($s -notmatch '["\r\n]') 'Unexpected argument quoting';return '"'+$s+'"'}
function PrincipalSID([string]$s){if($s.StartsWith('S-1-',[StringComparison]::OrdinalIgnoreCase)){return ([Security.Principal.SecurityIdentifier]::new($s)).Value};return ([Security.Principal.NTAccount]::new($s)).Translate([Security.Principal.SecurityIdentifier]).Value}
Need $ExecutionAuthorized.IsPresent 'Root full read and explicit one-shot registration/Run authorization required'
Fresh @($claim,$receipt,$regReceipt,$xmlPath,(Join-Path $logs ($tag+'.start.json')),(Join-Path $logs ($tag+'.call.json')),(Join-Path $logs ($tag+'.run.json')),(Join-Path $logs ($tag+'.log')),(Join-Path $logs ($tag+'.memcheck.log')),(Join-Path $logs ($tag+'_review_r3.check.json')),(Join-Path $tests ('outputs\'+$tag)))
$own=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_cryer_gpu_component_task_r3.json')),(E (Join-Path $PSScriptRoot 'upl_cryer_gpu_component_run_r3.ps1')),(E (Join-Path $tests 'notes\upl_cryer_gpu_component_run_r3.json')),(E (Join-Path $PSScriptRoot 'upl_cryer_gpu_component_review_r3.py')),(E (Join-Path $tests 'notes\upl_cryer_gpu_component_review_r3.json')))
$auditE=E (Join-Path ((Get-Item -LiteralPath $tests).Parent.Parent.FullName) '02_TerzaghiConsolidation_q0_PR\tests\logs\upl_mid_gpu_interruption_r1.check.json')
Need ($auditE.bytes -eq 1200299 -and $auditE.sha256 -ceq '15c9b4fb9e23f8e89c540db9ccf2aadb0b68ff48934109613bf63f86716c8160') 'Retained interruption audit changed'
$audit=J $auditE.path
Need ($audit.interruption_audited -eq $true -and $audit.all_observed_owned_processes_absent -eq $true -and $null -eq $audit.real_exit_code -and $audit.typed_exit_evidence_available -eq $false -and $audit.old_full_gate_preserved -eq $true -and $audit.GPU.completed_six_probes -eq $false) 'No recovery from an invented completed r2'
$helperE=E (Join-Path $logs ('upl_cryer_gpu_component_'+$Configuration+'_r2.helper.json'));$h=J $helperE.path
Need ($h.passed -and $h.configuration -ceq $Configuration -and $h.stage -ceq 'upl_cryer_gpu_component_build_r2' -and $h.status -ceq 'frozen_cryer_GPU_component_linked_not_run' -and $h.GPU_non_main_objects -eq 110 -and $h.link_object_count -eq 111 -and $h.actual_headers_archived_not_live -and $h.frozen_build_program_inputs_runtime_unchanged) 'Selected unchanged r2 helper build required'
$program=E $h.program.path;Need ($program.bytes -eq $h.program.bytes -and $program.sha256 -ceq $h.program.sha256 -and [IO.Path]::GetFileName($program.path) -ceq 'upl_cryer_gpu_component_r2.exe') 'Exact retained r2 component program required'
if($Configuration -ceq 'Debug'){Need ($helperE.path -ieq $audit.GPU.helper.path -and $helperE.bytes -eq $audit.GPU.helper.bytes -and $helperE.sha256 -ceq $audit.GPU.helper.sha256) 'Debug helper differs from interrupted audit'}
$debugE=$null
if($Configuration -ceq 'Release'){$debugE=E (Join-Path $logs 'upl_cryer_gpu_component_Debug_probe_r3_review_r3.check.json');$d=J $debugE.path;Need ($d.stage -ceq 'upl_cryer_gpu_component_review_r3' -and $d.passed -and $d.configuration -ceq 'Debug' -and $d.typed_owned_tool_exit0 -and $d.memcheck_errors -eq 0 -and $d.memcheck_leaks -eq 0 -and $d.component_completion_verified -and $d.physical_acceptance -eq $false) 'Fresh r3 Debug review required before Release'}
$active=@(Get-CimInstance Win32_Process -Filter "Name LIKE 'DualSPHysics%.exe' OR Name LIKE 'upl_%.exe' OR Name = 'compute-sanitizer.exe'")
Need ($active.Count -eq 0) 'A surviving project process requires diagnosis; do not register/launch another'
$owner=Join-Path $PSScriptRoot 'upl_cryer_gpu_component_run_r3.ps1';$shell=E (Join-Path ([Environment]::SystemDirectory) 'WindowsPowerShell\v1.0\powershell.exe')
$argv=@('-NoLogo','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',$owner,'-Configuration',$Configuration,'-ExecutionAuthorized')
$argumentText=($argv|ForEach-Object{Quoted $_}) -join ' '
$identity=[Security.Principal.WindowsIdentity]::GetCurrent();$sid=$identity.User.Value
$bindings=$own+@($auditE,$helperE,$program,$shell);if($debugE){$bindings+=@($debugE)};V $bindings
Save $claim ([ordered]@{stage='upl_cryer_gpu_component_task_attempt_r3';configuration=$Configuration;utc=[DateTime]::UtcNow.ToString('o');task_name=$taskName;task_path=('\'+$taskName);task_create_only_flag=2;task_action_program=$shell;task_action_arguments=$argv;task_action_argument_string=$argumentText;task_working_directory=$tests;principal_sid=$sid;logon_type=3;run_level=0;triggers=0;retries=0;ignore_new_instances=2;hidden=$true;maximum_task_duration='PT2H';inputs=$bindings;registration_or_Run_completed_by_attempt_record=$false;native_exit_captured=$false;physical_acceptance=$false})
$registered=$null;$registrationEntry=$null;$xmlEntry=$null;$registeredOK=$false;$runInvoked=$false;$runReturned=$false;$instanceId=$null;$enginePID=$null;$instanceState=$null;$taskState=$null;$schedulerResult=$null;$schedulerLastRun=$null;$failure=$null
try{
  $service=New-Object -ComObject 'Schedule.Service';$service.Connect();$root=$service.GetFolder('\');$definition=$service.NewTask(0)
  $definition.RegistrationInfo.Description='One fresh bounded Cryer GPU arithmetic component r3 after audited interruption; no recurrence, notifier or physical trajectory.'
  $definition.Principal.UserId=$sid;$definition.Principal.LogonType=3;$definition.Principal.RunLevel=0
  $settings=$definition.Settings;$settings.Enabled=$true;$settings.Hidden=$true;$settings.AllowDemandStart=$true;$settings.MultipleInstances=2;$settings.ExecutionTimeLimit='PT2H';$settings.RestartCount=0;$settings.DisallowStartIfOnBatteries=$false;$settings.StopIfGoingOnBatteries=$false;$settings.RunOnlyIfNetworkAvailable=$false;$settings.StartWhenAvailable=$false;$settings.AllowHardTerminate=$true
  $action=$definition.Actions.Create(0);$action.Path=$shell.path;$action.Arguments=$argumentText;$action.WorkingDirectory=$tests
  Need ($definition.Triggers.Count -eq 0 -and $definition.Actions.Count -eq 1) 'Demand-only single-action definition required'
  # TASK_CREATE=2 only. An existing task is not updated or overwritten. No password/elevation/fallback.
  $registered=$root.RegisterTaskDefinition($taskName,$definition,2,$sid,$null,3,$null);$registeredOK=$true
  $actual=$registered.Definition;$actualAction=$actual.Actions.Item(1)
  Need ($registered.Path -ceq ('\'+$taskName) -and $actual.Triggers.Count -eq 0 -and $actual.Actions.Count -eq 1 -and $actual.Principal.LogonType -eq 3 -and $actual.Principal.RunLevel -eq 0 -and (PrincipalSID $actual.Principal.UserId) -ceq $sid -and $actual.Settings.Enabled -and $actual.Settings.Hidden -and $actual.Settings.AllowDemandStart -and $actual.Settings.MultipleInstances -eq 2 -and $actual.Settings.RestartCount -eq 0 -and $actual.Settings.ExecutionTimeLimit -ceq 'PT2H' -and $actual.Settings.AllowHardTerminate -and !$actual.Settings.DisallowStartIfOnBatteries -and !$actual.Settings.StopIfGoingOnBatteries -and !$actual.Settings.RunOnlyIfNetworkAvailable -and !$actual.Settings.StartWhenAvailable -and $actualAction.Type -eq 0 -and $actualAction.Path -ieq $shell.path -and $actualAction.Arguments -ceq $argumentText -and $actualAction.WorkingDirectory -ieq $tests) 'Actual registered demand-only/least-privilege/action settings differ'
  Fresh @($xmlPath);[IO.File]::WriteAllText($xmlPath,[string]$registered.Xml,(New-Object Text.UTF8Encoding($false)));$xmlEntry=E $xmlPath
  Save $regReceipt ([ordered]@{stage='upl_cryer_gpu_component_task_registered_r3';configuration=$Configuration;registered_utc=[DateTime]::UtcNow.ToString('o');task_name=$taskName;task_path=$registered.Path;XML=$xmlEntry;claim=(E $claim);inputs=$bindings;task_action_arguments=$argv;task_action_argument_string=$argumentText;actual_definition_verified=$true;create_only_no_old_task_mutated=$true;triggers=0;retry_count=0;maximum_task_duration='PT2H';principal_sid=$sid;logon_type=3;run_level=0;hidden=$true;Run_not_yet_invoked=$true;native_exit_captured=$false;physical_acceptance=$false})
  $registrationEntry=E $regReceipt
  V ($bindings+@($xmlEntry,$registrationEntry));$again=$root.GetTask($taskName)
  Need ([string]$again.Xml -ceq [IO.File]::ReadAllText($xmlPath)) 'Task definition changed before its single Run'
  $active=@(Get-CimInstance Win32_Process -Filter "Name LIKE 'DualSPHysics%.exe' OR Name LIKE 'upl_%.exe' OR Name = 'compute-sanitizer.exe'");Need ($active.Count -eq 0) 'Project process appeared before Run; leave this demand-only task unrun'
  $runInvoked=$true;$instance=$again.Run($null);$runReturned=$true
  $instanceId=[string]$instance.InstanceGuid;Need (![string]::IsNullOrWhiteSpace($instanceId)) 'Scheduler returned no instance identity; inspect before any further action'
  $enginePID=[long]$instance.EnginePID;$instanceState=[int]$instance.State;$latest=$root.GetTask($taskName);$taskState=[int]$latest.State;$schedulerResult=[long]$latest.LastTaskResult;$schedulerLastRun=$latest.LastRunTime.ToUniversalTime().ToString('o')
}catch{$failure=$_.Exception.Message}
Save $receipt ([ordered]@{stage='upl_cryer_gpu_component_task_launch_r3';configuration=$Configuration;ended_utc=[DateTime]::UtcNow.ToString('o');claim=(E $claim);registered=$registeredOK;registration_receipt=$registrationEntry;task_XML=$xmlEntry;task_name=$taskName;task_path=('\'+$taskName);Run_invoked=[bool]$runInvoked;Run_returned=[bool]$runReturned;scheduler_instance_id=$instanceId;scheduler_engine_PID=$enginePID;scheduler_instance_state=$instanceState;task_state_observed=$taskState;scheduler_LastTaskResult_observed=$schedulerResult;scheduler_LastRunTime_utc=$schedulerLastRun;failure=$failure;launcher_completed_without_error=(!$failure -and $registeredOK -and $runReturned);native_start_not_invoked_by_launcher=(!$runInvoked);native_start_or_completion_independently_verified=$false;typed_native_exit_captured_by_launcher=$false;native_exit_code=$null;scheduler_status_is_not_native_exit=$true;demand_only_no_triggers_or_retries=$true;automatic_follow_up_or_notifier=$false;automatic_fallback_or_second_Run=$false;old_tasks_or_outputs_overwritten=$false;inputs=$bindings;physical_acceptance=$false})
if($failure){throw ('One-shot launch not fully verified; inspect retained receipts and actual task/process state, never retry/fallback automatically: '+$receipt)}
Write-Output ('Single demand Run submitted; actual owner/call/completion and offline gates remain required: '+$receipt)
